(1642588, 222069, 29553, '<td valign="top">A little dark &amp; grainy.</td>', 'A little dark & grainy.', '2005-08-24 22:31:56.000000', NULL, 1),
(1642589, 222163, 40155, '<td valign="top">Amazing.  I have no idea how you did this.  Original.</td>', 'Amazing.  I have no idea how you did this.  Original.', '2005-08-24 22:32:04.000000', NULL, 1),
(1642590, 220368, 29553, '<td valign="top">Neato!</td>', 'Neato!', '2005-08-24 22:32:13.000000', NULL, 1),
