(1642597, 219987, 41675, '<td valign="top">Nice interpretation of the challenge and good composition. Lucky mouse! Hope he doesn''t bring over too many friends. :-)</td>', 'Nice interpretation of the challenge and good composition. Lucky mouse! Hope he doesn''t bring over too many friends. :-)', '2005-08-24 22:34:16.000000', NULL, 1),
(1642600, 222059, 40155, '<td valign="top">Clear and clean shot with the lighting working in your favor.</td>', 'Clear and clean shot with the lighting working in your favor.', '2005-08-24 22:34:58.000000', NULL, 1),
