INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1642610, 222091, 41675, '<td valign="top">It''s refreshing to see a different take on the milk splashes. Good contrast and lighting. 9</td>', 'It''s refreshing to see a different take on the milk splashes. Good contrast and lighting. 9', '2005-08-24 22:36:10.000000', NULL, 1),
(1642612, 220991, 29553, '<td valign="top">cool concept.  I think if the background was darker, I would like this more.</td>', 'cool concept.  I think if the background was darker, I would like this more.', '2005-08-24 22:36:35.000000', NULL, 1),
(1642615, 222163, 10634, '<td valign="top">nice.... excellent timing.</td>', 'nice.... excellent timing.', '2005-08-24 22:36:46.000000', NULL, 1),
(1642616, 222134, 41675, '<td valign="top">I like the milk bone in the dish, but for me there is too much of the dog''s nose. Points for ingenuity too.</td>', 'I like the milk bone in the dish, but for me there is too much of the dog''s nose. Points for ingenuity too.', '2005-08-24 22:36:52.000000', NULL, 1),
(1642618, 220038, 29553, '<td valign="top">You must have put a lot of thought into this.  Just wish is were a little sharper.</td>', 'You must have put a lot of thought into this.  Just wish is were a little sharper.', '2005-08-24 22:37:28.000000', NULL, 1),
(1642620, 219544, 41675, '<td valign="top">Cute take on the challnege. I wonder how long it took and how many eggs you painted until you did one you liked. I like the complimentary striped vase in the background, but I find the red coffee mug a bit distractig from the overall black and white feel.</td>', 'Cute take on the challnege. I wonder how long it took and how many eggs you painted until you did one you liked. I like the complimentary striped vase in the background, but I find the red coffee mug a bit distractig from the overall black and white feel.', '2005-08-24 22:37:57.000000', NULL, 1),
(1642622, 222031, 41675, '<td valign="top">I think I would have appreciated this photo more if it had been in color.</td>', 'I think I would have appreciated this photo more if it had been in color.', '2005-08-24 22:38:31.000000', NULL, 1),
(1642623, 221834, 29553, '<td valign="top">I could probably do without the to spots in the upper left.</td>', 'I could probably do without the to spots in the upper left.', '2005-08-24 22:38:40.000000', NULL, 1),
(1642625, 220021, 41675, '<td valign="top">I like the idea but the photo seems a bit too grainy for me. I do like how you caught the one drip in mid-air though.</td>', 'I like the idea but the photo seems a bit too grainy for me. I do like how you caught the one drip in mid-air though.', '2005-08-24 22:39:08.000000', NULL, 1),
(1642626, 222063, 10634, '<td valign="top">Awwww  I remember those days with my children. Hopefully, others will appreciate how precious a moment you have captured. I might have played a bit with the brightness/contrast just to see what the result would be.</td>', 'Awwww  I remember those days with my children. Hopefully, others will appreciate how precious a moment you have captured. I might have played a bit with the brightness/contrast just to see what the result would be.', '2005-08-24 22:39:29.000000', NULL, 1),
(1642627, 222091, 29553, '<td valign="top">Wow.  Impressive.  Would love to know how you did that.</td>', 'Wow.  Impressive.  Would love to know how you did that.', '2005-08-24 22:39:39.000000', NULL, 1),
