(1646622, 222012, 42957, '<td valign="top">Nice intimate moment with the cows...except I''ve seen WAY  too many cows.</td>', 'Nice intimate moment with the cows...except I''ve seen WAY  too many cows.', '2005-08-26 00:58:44.000000', NULL, 1),
(1646627, 222029, 42957, '<td valign="top">This makes me want to eat ice cream, but other than that, just another picture.</td>', 'This makes me want to eat ice cream, but other than that, just another picture.', '2005-08-26 01:00:44.000000', NULL, 1),
