(1650279, 220307, 20530, '<td valign="top">Nice crop, and what a beautiful child. Good job of capturing the expression in the eyes.</td>', 'Nice crop, and what a beautiful child. Good job of capturing the expression in the eyes.', '2005-08-27 18:37:04.000000', NULL, 1),
(1650286, 222163, 7304, '<td valign="top">Neat shot. Nice idea, 8</td>', 'Neat shot. Nice idea, 8', '2005-08-27 18:42:14.000000', NULL, 1),
(1650294, 221516, 20530, '<td valign="top">Love the cow, the colors and the angle. It would have been better, IMO, with softer light and minus the con-trail in sky.</td>', 'Love the cow, the colors and the angle. It would have been better, IMO, with softer light and minus the con-trail in sky.', '2005-08-27 18:45:30.000000', NULL, 1),
(1650298, 221985, 20530, '<td valign="top">Especially considering that appears to be a steer! J/K. I like the colors and how you captured his atttention.</td>', 'Especially considering that appears to be a steer! J/K. I like the colors and how you captured his atttention.', '2005-08-27 18:47:04.000000', NULL, 1),
