(1652800, 219143, 38476, '<td valign="top">Sepia &amp; the old fashioned soda-fountain style glasses look really great together. Wish all the glasses were in focus &amp; that there weren''t those distracting reflections in the glasses, though. 7.</td>', 'Sepia & the old fashioned soda-fountain style glasses look really great together. Wish all the glasses were in focus & that there weren''t those distracting reflections in the glasses, though. 7.', '2005-08-28 22:34:34.000000', NULL, 1),
(1652801, 222124, 38476, '<td valign="top">Interesting crop</td>', 'Interesting crop', '2005-08-28 22:34:56.000000', NULL, 1),
(1652814, 220518, 38476, '<td valign="top">Very interesting approach to the challenge. I like your creativity. I rated this a 5, but had it not been essentially a photograph of existing artwork I would have rated it much higher.</td>', 'Very interesting approach to the challenge. I like your creativity. I rated this a 5, but had it not been essentially a photograph of existing artwork I would have rated it much higher.', '2005-08-28 22:40:28.000000', NULL, 1),
